	"vbipsupplier/view/fragment/CardInfo.fragment.xml":'<core:FragmentDefinition \n\txmlns="sap.m"\n    xmlns:core="sap.ui.core"><VBox id="idMainP1.VBox" class="sapUiSmallMargin" alignItems="Center" \n\t\t  visible="{PageModel>/pageFlow/cardInfo}"><VBox id="idContent.VBox" class="customBoxContent" alignItems="Center" width="50%"><VBox id="Card.VBox" class="customBoxCard" width="350px" height="200px"><HBox justifyContent="SpaceBetween"><Text id="idTitleP1.Text" text="VISA" class="customTextCard"/><Button id="ideye.Button" icon="{CardInfo>/btnIcon}" press="onShowInfor"></Button></HBox><VBox id="idCardSpace.VBox" height="50px"/><HBox justifyContent="SpaceBetween"><Text id="idText1.Text" text="Card Number" class="customTextCard"/><Text id="idText4.Value" text="{CardInfo>/cardNumber}" class="customTextCard" ></Text></HBox><HBox justifyContent="SpaceBetween"><Text id="idText2.Text" text="Expired Date" class="customTextCard"/><Text id="idText2.Value" text="{CardInfo>/expiredate}" class="customTextCard"></Text></HBox><HBox justifyContent="SpaceBetween"><Text id="idText3.Text" text="CVV" class="customTextCard"/><Text id="idText3.Value" text="{CardInfo>/cvv2}" class="customTextCard"></Text></HBox></VBox></VBox></VBox></core:FragmentDefinition>\n',
