	"vbipsupplier/view/fragment/LandingPage.fragment.xml":'<core:FragmentDefinition \n\txmlns="sap.m"\n    xmlns:core="sap.ui.core"><VBox id="idMainP1.VBox" class="sapUiSmallMargin" alignItems="Center" \n\t\t  visible="{PageModel>/pageFlow/landing}"><VBox id="idItemP1.VBox" class="customBoxContent" width="65%"><Text id="idTitleP1.Text" text="Invalid URL, please access correct URL from your email" \n\t\t\t\t  class="customSubtitle1" visible="{LandingText>/invalid}"/><Text id="idTitleP2.Text" text="Invalid URL, your URL has expired" \n\t\t\t\t  class="customSubtitle1" visible="{LandingText>/expire}"/><Text id="idTitleP3.Text" text="Your session is ended, please contact to Buyer for more information." \n\t\t\t\t  class="customSubtitle1" visible="{LandingText>/report}"/></VBox></VBox></core:FragmentDefinition>\n',
	"vbipsupplier/view/fragment/OneTimePassword.fragment.xml":'<core:FragmentDefinition \n\txmlns="sap.m"\n    xmlns:core="sap.ui.core"><VBox id="idMain.VBox" class="sapUiSmallMargin" visible="{PageModel>/pageFlow/otp}"><VBox id="idItem.VBox" alignItems="Center"><VBox id="idPanelContent.VBox" class="customBoxContent" width="50%"><Text id="idSendMail.Text" text="{i18n>sendOTPMail}" class="mainTitle"/><Text id="idYourOTPSent.Text" \n\t\t\t\t   \t  text="{i18n>yourOTPSent} ({SupplierInfo>/supplier/emailID} {SupplierInfo>/supplier/supplierName}) \n\t\t\t\t\t  \t\t{i18n>reachOut} {SupplierInfo>/buyer/legalName}" \n\t\t\t\t\t  class="customText"/><VBox id="idSpace1.VBox" height="32px"/><Label id="idOnetimePassword.Label" text="{i18n>OTP}"></Label><Input id="idOTP.Input" width="150px" maxLength="6"/><Link id="idResendOTP.Link" text="{i18n>resendOTP}" press="onResendOTPLinkPress"/><VBox id="idSpace2.VBox" height="32px"/><HBox id="idButton.HBox"><Button id="idContinue.Button3" class="classButtonRow" type="Emphasized" \n\t\t\t\t\t\t\ttext="{i18n>continue}" press="onContinueButtonPress"/></HBox></VBox></VBox></VBox></core:FragmentDefinition>\n',
	"vbipsupplier/view/fragment/ShareholderPopup.fragment.xml":'<core:FragmentDefinition\n    xmlns="sap.m"\n    xmlns:core="sap.ui.core"\n    xmlns:f="sap.ui.layout.form"><Dialog id="idPopup.Dialog" contentWidth="50%"\n            showHeader="false" afterClose="onDialogAfterClose"><VBox id="idTitle.VBox" class="customDialog1"><VBox id="idShareholder.VBox" width="100%"><Title id="idShareholderDetails.Title" class="customHeadline1"\n                            text="{i18n>shareholderDetails}"/><Text id="idShareholderDetails.Text" text="{i18n>shareholderDetails}"\n                            class="customSubtitle1"/><Label id="idName.Label" class="customLabel" text="{i18n>name}"/><Input id="idName.Input" value="{ShareholderPopupModel>/popup/name}"/><Label id="idShareholderPercentage.Label" text="{i18n>ShareholderPercentage}" \n                            class="customLabel"/><Input id="idShareholderPercentage.Input" value="{ShareholderPopupModel>/popup/sharePercentage}"/><Label id="idShareholderAddress.Label" text="{i18n>shareholderAddress}" \n                            class="customLabel"/><Input id="idShareholderAddress.Input" value="{ShareholderPopupModel>/popup/address}"/><VBox id="idSpacePopup.VBox" height="24px"/><Text id="idIdentityProof.Text" text="{i18n>identityProof}" \n                            class="customSubtitle1"/><Text id="idDescription.Text" text="{i18n>uploadDescription}" \n                            class="customText"/><Label id="idDoctype.Label" text="{i18n>documentType}" class="customLabel"/><ComboBox id="idDocType.Select" items="{path: \'F4>/docType\'}" width="100%"\n                                  selectedKey="{ShareholderPopupModel>/popup/docType}"><core:Item id="idDocType.Item" key="{F4>validIDDocument}" text="{F4>validIDDocument}"/></ComboBox><Label id="idDocNum.Label" text="{i18n>documentNumber}" class="customLabel"/><Input id="idDocNum.Input" value="{ShareholderPopupModel>/popup/docNum}"/><Label id="idNameOnDoc.Label" text="{i18n>nameOnDocument}" class="customLabel"/><Input id="idNameOnDoc.Input" value="{ShareholderPopupModel>/popup/nameOnDoc}"/><Label id="idDateOfBirth.Label" text="{i18n>dateOfBirth}" class="customLabel"/><DatePicker id="idDateOfBirth.DatePicker"\n                                    value="{\n                                                \'path\':\'ShareholderPopupModel>/popup/dateOfBirth\',\n                                                \'type\':\'sap.ui.model.type.Date\',\n                                                \'formatOptions\': {\n                                                    \'pattern\': \'yyyy-MM-dd\'\n                                                    }\n                                            }"/><Label id="idDateOfIssue.Label" text="{i18n>dateOfIssue}" class="customLabel"/><DatePicker id="idDateOfIssue.DatePicker" \n                                    value="{\n                                                \'path\':\'ShareholderPopupModel>/popup/issuingDate\',\n                                                \'type\':\'sap.ui.model.type.Date\',\n                                                \'formatOptions\': {\n                                                    \'pattern\': \'yyyy-MM-dd\'\n                                                    }\n                                            }"/><Label id="idDateOfExpiry.Label" text="{i18n>dateOfExpiry}" class="customLabel"/><DatePicker id="idDateOfExpiry.DatePicker" \n                                    value="{\n                                                \'path\':\'ShareholderPopupModel>/popup/expiryDate\',\n                                                \'type\':\'sap.ui.model.type.Date\',\n                                                \'formatOptions\': {\n                                                    \'pattern\': \'yyyy-MM-dd\'\n                                                    }\n                                            }"/><HBox id="idUploadSH.HBox" class="customUploadBox"\n                              visible="{ShareholderPopupModel>/popup/uploadVisible}"><VBox id="idIconUploadSH.VBox" class="customUploadItem1" width="10%"><core:Icon id="idUploadSH.Icon" src="sap-icon://upload-to-cloud" \n                                        size="30px" color="#1434CB"/></VBox><VBox id="idTextUploadSH.VBox" class="customUploadItem2" width="60%"><Text id="idUploadSH.Text" class="classTextBold" text="{i18n>clickToUpload}"/><Text id="idFileTypeSH.Text" text="{i18n>fileType}"/></VBox><VBox id="idbuttonUploadSH.VBox" class="customUploadItem3"><Button id="idUploadFileSH.Button" type="Transparent" \n                                        text="Select file" press="onUploadFileSH"/></VBox></HBox><HBox id="idFileSH.HBox" class="customFileNameBox"\n                              visible="{ShareholderPopupModel>/popup/fileVisible}"><VBox id="idIconFileSH.VBox" class="customUploadItem1"><core:Icon id="idDownloadFileSH.Icon" src="sap-icon://attachment-photo" \n                                            size="24px" color="#1434CB" press="onDownloadFileSH"></core:Icon></VBox><VBox id="idFileNameSH.VBox" class="customUploadItem2" width="85%"><Text id="idFileNameSH.Text" text="{ShareholderPopupModel>/popup/fileName}"/></VBox><VBox id="idDeleteFileSH.VBox" class="customUploadItem3"><core:Icon id="idDeleteFileSH.Icon" src="sap-icon://decline" \n                                            size="24px" color="#1434CB" press="onDeleteFileSH"></core:Icon></VBox></HBox></VBox></VBox><HBox id="idAction.HBox" class="customActionBox1"><Button id="idSave.Button" text="{i18n>save}" type="Emphasized" press="onSave"/><Button id="idCancel.Button" text="{i18n>cancel}" type="Transparent" press="onCancel"/></HBox></Dialog></core:FragmentDefinition>\n',
